#!/usr/bin/env node
// Agent-team analytics ALERTING (Phase 4)
// Incremental anomaly detection over the ledger. Alerts only on NEW runs (tracked in
// .alert-state.json) so healthy periods stay silent and old runs are not re-alerted.
//
// CRITICAL alerts are meant to WAKE the owner (the scheduled workflow throws on critical>0).
// WARNING alerts are logged to alerts.jsonl for the next digest.
//
// Output:
//   - appends fired alerts to alerts.jsonl
//   - prints a single JSON summary line to stdout (last line): {critical,warning,newRuns,summary}
//   - exits non-zero when critical>0 (belt-and-suspenders for shell-level failure)
//
// Usage: node alert.mjs [--ledger PATH] [--json] [--reset]

import { readFileSync, writeFileSync, existsSync, appendFileSync } from "node:fs";
import { join } from "node:path";
import { homedir } from "node:os";

const args = process.argv.slice(2);
const arg = (f, d) => (args.includes(f) ? args[args.indexOf(f) + 1] : d);
const DIR = join(homedir(), "agent-team", "analytics");
const ledgerPath = arg("--ledger", join(DIR, "ledger.jsonl"));
const alertsPath = join(DIR, "alerts.jsonl");
const statePath = arg("--state", join(DIR, ".alert-state.json"));
const JSON_ONLY = args.includes("--json");

// Tunable thresholds (research §D — validate against your own baseline)
const T = {
  contextCritUtil: 0.80,      // §2 context rot / lost-in-the-middle
  cacheHitLow: 0.30,          // §2 prompt caching
  costSpikeMultiplier: 3,     // §D anomaly vs agent median
  minRunsForBaseline: 3,      // don't spike-alert until baseline exists
  highTurns: 8,               // §3 loop guardrails
  highTools: 15,
  dailyBurnUsd: 5.00,         // §D burn-rate: alert if last-24h spend exceeds this
};

const num = (x) => (typeof x === "number" && isFinite(x) ? x : 0);
const usd = (x) => "$" + num(x).toFixed(4);
const pct = (x) => (x == null ? "—" : (x * 100).toFixed(1) + "%");
const median = (a) => { if (!a.length) return 0; const s=[...a].sort((x,y)=>x-y); const m=s.length>>1; return s.length%2?s[m]:(s[m-1]+s[m])/2; };

if (!existsSync(ledgerPath)) { console.log(JSON.stringify({ critical: 0, warning: 0, newRuns: 0, summary: "No ledger; run collect.mjs first." })); process.exit(0); }
const rows = readFileSync(ledgerPath, "utf8").split("\n").map((l)=>l.trim()).filter(Boolean).map((l)=>JSON.parse(l));
const leaf = rows.filter((r) => r.costUsd != null || r.totalTokens != null);

// state: which runIds already alerted
let state = { alerted: [] };
if (!args.includes("--reset") && existsSync(statePath)) { try { state = JSON.parse(readFileSync(statePath, "utf8")); } catch {} }
const alreadyAlerted = new Set(state.alerted || []);

// per-agent median cost baseline (over ALL leaf runs, not just new)
const byAgent = new Map();
for (const r of leaf) { const k = r.agent || "unknown"; (byAgent.get(k) || byAgent.set(k, []).get(k)).push(r); }
const agentMedian = new Map();
for (const [k, list] of byAgent) agentMedian.set(k, { med: median(list.map((r)=>num(r.costUsd))), n: list.length });

const newRuns = leaf.filter((r) => !alreadyAlerted.has(r.runId));
const fired = [];
const push = (sev, r, rule, msg) => fired.push({ ts: new Date().toISOString(), sev, rule, runId: r.runId, agent: r.agent || "unknown", model: r.model, msg });

for (const r of newRuns) {
  const agent = r.agent || "unknown";
  const base = agentMedian.get(agent) || { med: 0, n: 0 };
  // CRITICAL
  if (r.contextUtilization != null && r.contextUtilization >= T.contextCritUtil)
    push("CRITICAL", r, "context-util", `Context utilization ${pct(r.contextUtilization)} ≥ ${pct(T.contextCritUtil)}. Compact/retrieve or isolate in a fresh sub-agent.`);
  if (base.n >= T.minRunsForBaseline && base.med > 0 && num(r.costUsd) > base.med * T.costSpikeMultiplier)
    push("CRITICAL", r, "cost-spike", `Cost ${usd(r.costUsd)} > ${T.costSpikeMultiplier}× ${agent} median (${usd(base.med)}). Check scope; add usageBudget.`);
  if (num(r.turnCount) >= T.highTurns || num(r.toolCount) >= T.highTools)
    push("CRITICAL", r, "runaway-loop", `High activity (turns=${r.turnCount ?? "?"}, tools=${r.toolCount ?? "?"}). Add max-turn/tool guardrails.`);
  // WARNING
  const cacheDenom = num(r.inputTokens) + num(r.cacheReadTokens) + num(r.cacheWriteTokens);
  if (r.cacheHitRatio != null && r.cacheHitRatio < T.cacheHitLow && cacheDenom > 2000)
    push("WARNING", r, "low-cache", `Cache hit ${pct(r.cacheHitRatio)} < ${pct(T.cacheHitLow)}. Stabilize prompt prefix for caching.`);
  if (r.acceptanceStatus === "rejected")
    push("WARNING", r, "acceptance-rejected", `Acceptance rejected. Gate any change behind an eval before/after (§3.6).`);
}

// Burn-rate: last 24h spend across ALL runs (not just new) — CRITICAL, de-duped per day
const now = Date.now();
const last24 = leaf.filter((r) => r.startedAt && (now - r.startedAt) <= 24*3600*1000);
const burn = last24.reduce((s, r) => s + num(r.costUsd), 0);
const burnKey = "burn-" + new Date().toISOString().slice(0,10);
if (burn > T.dailyBurnUsd && !alreadyAlerted.has(burnKey)) {
  fired.push({ ts: new Date().toISOString(), sev: "CRITICAL", rule: "burn-rate", runId: burnKey, agent: "*", model: null,
    msg: `24h spend ${usd(burn)} exceeds daily budget ${usd(T.dailyBurnUsd)} across ${last24.length} runs.` });
}

// persist
const critical = fired.filter((f) => f.sev === "CRITICAL").length;
const warning = fired.filter((f) => f.sev === "WARNING").length;
if (fired.length) appendFileSync(alertsPath, fired.map((f)=>JSON.stringify(f)).join("\n") + "\n");
const newAlerted = new Set([...alreadyAlerted, ...newRuns.map((r)=>r.runId)]);
if (burn > T.dailyBurnUsd) newAlerted.add(burnKey);
writeFileSync(statePath, JSON.stringify({ alerted: [...newAlerted].slice(-5000), updatedAt: new Date().toISOString() }, null, 0));

const summaryLines = fired.map((f) => `[${f.sev}] ${f.agent} ${String(f.runId).slice(0,8)} ${f.rule}: ${f.msg}`);
const summary = fired.length ? summaryLines.join(" | ") : `Healthy: ${newRuns.length} new runs, 24h spend ${usd(burn)}.`;

if (!JSON_ONLY) {
  console.log(`Alert check: ${newRuns.length} new runs · 24h spend ${usd(burn)}`);
  for (const l of summaryLines) console.log("  " + l);
  if (!fired.length) console.log("  (no alerts)");
}
console.log(JSON.stringify({ critical, warning, newRuns: newRuns.length, burnUsd: +burn.toFixed(4), summary }));
process.exit(critical > 0 ? 2 : 0);
